import rcb_dtb as R, numpy as np, mujoco
s=R.Session('/app/instance.json'); d=s.data;m=s.model
print('q',s.state()['q'][:7]);print('object',s.state()['object_pos'],s.state()['object_quat_wxyz']);print('palm',s.state()['palm_pos']);
for n in ['palmworld','palmleft_thumb_PP','palmleft_thumb_DP','palmleft_index_PP','palmleft_index_DP','palmleft_middle_DP','palmleft_ring_DP','palmleft_pinky_DP']:
 try:
  b=m.body(n).id;print(n,d.xpos[b], d.xmat[b].reshape(3,3))
 except Exception as e: print(e)
print('limits',s.lower,s.upper)
print('body names', [(i,m.body(i).name) for i in range(m.nbody) if 'palm' in m.body(i).name][:35]);
print('obj mass',m.body('object').subtreemass)
import imageio.v2 as imageio
for c in ('front','top','side','oblique'):imageio.imwrite('/app/output/'+c+'.png',s.render(c,size=(640,480)))
PY

